/**
 * Qaida-style drills ("Birikma") for every lesson, generated by rules from the letters learned so far.
 * Used as mock data and, through `npm run seed:sql`, as the database seed, so both always match.
 *
 * Each lesson gets a fixed list, simple → harder:
 *   1. the letter with zabar, zer, pesh             بَ بِ بُ
 *   2. madd (long aa)                               بَا
 *   3. an earlier letter + this letter              أَبَ
 *   4. earlier letter + this letter + another       أَتَبَ
 *   5. jazm (sukun)                                 أَبْ
 *   6. tashdid (shadda)                             أَبَّ
 *   7. tanwin                                       بًا بٍ بٌ
 *   8. gʻunna (only once nun or mim is learned)     بَنَّ
 * The Alif lesson only has 1 and آ (madd), as there is nothing to join yet.
 *
 * Arabic rules the generator respects:
 * - Alif never carries a vowel itself: at the start of a word the vowel sits on a hamza (أَ إِ أُ);
 *   elsewhere alif only appears as a long vowel after zabar (بَا) or after ikki zabar (بًا).
 * - Jazm and tashdid are never on the first letter of a word.
 * - Words are random but repeatable: each lesson uses its own fixed seed.
 */
import type { DrillFeature } from '@/types/letter'

export const FATHA = 'َ' // zabar
export const KASRA = 'ِ' // zer
export const DAMMA = 'ُ' // pesh
export const SUKUN = 'ْ' // jazm
export const SHADDA = 'ّ' // tashdid
export const FATHATAN = 'ً' // ikki zabar
export const KASRATAN = 'ٍ' // ikki zer
export const DAMMATAN = 'ٌ' // ikki pesh

const ALIF = 'ا'
const NASAL = ['ن', 'م']
const HARAKAT = [FATHA, KASRA, DAMMA]

export interface DrillSpec {
  text: string
  features: DrillFeature[]
}

/** Small deterministic random generator (mulberry32). */
function seeded(seed: number): () => number {
  let state = seed >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let t = state
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** A letter with a short vowel. Alif can only take one at the start of a word, written on a hamza. */
function voweled(letter: string, vowel: string): string {
  if (letter === ALIF) return vowel === KASRA ? `إ${KASRA}` : `أ${vowel}`
  return letter + vowel
}

/**
 * The drills for one lesson.
 * @param alphabet - the letters in alphabet order, e.g. ['ا', 'ب', 'ت', …]
 * @param lessonOrder - which lesson (1 = Alif); only letters up to this one are used
 */
export function buildDrills(alphabet: readonly string[], lessonOrder: number): DrillSpec[] {
  const pool = alphabet.slice(0, lessonOrder)
  const current = pool.at(-1)
  if (!current) return []

  const previous = pool.slice(0, -1)
  const random = seeded(lessonOrder * 7919)
  const pick = <T,>(items: readonly T[]): T => items[Math.floor(random() * items.length)]!
  const vowel = () => pick(HARAKAT)
  // Alif can't carry a vowel in the middle or at the end of a word.
  const canTakeVowelInside = pool.filter((letter) => letter !== ALIF)

  const drills: DrillSpec[] = []
  const add = (text: string, features: DrillFeature[]) => {
    if (!drills.some((drill) => drill.text === text)) drills.push({ text, features })
  }

  // 1. Zabar, zer, pesh on this letter.
  add([FATHA, KASRA, DAMMA].map((v) => voweled(current, v)).join(' '), ['harakat'])

  if (current === ALIF) {
    add('آ', ['madd'])
    return drills
  }

  // 2. Madd: a long "aa".
  add(current + FATHA + ALIF, ['madd'])
  // 3. An earlier letter, then this one.
  add(voweled(pick(previous), vowel()) + current + vowel(), ['harakat'])
  // 4. Three letters: an earlier one, this one, and one more.
  add(voweled(pick(previous), vowel()) + current + vowel() + pick(canTakeVowelInside) + vowel(), ['harakat'])
  // 5. Jazm (sukun) on this letter.
  add(voweled(pick(previous), vowel()) + current + SUKUN, ['sukun'])
  // 6. Tashdid on this letter.
  // (Nun or mim with tashdid is always read with gʻunna.)
  add(voweled(pick(previous), vowel()) + current + SHADDA + vowel(), NASAL.includes(current) ? ['shadda', 'ghunna'] : ['shadda'])
  // 7. Tanwin: ikki zabar (written with an alif), ikki zer, ikki pesh.
  add([current + FATHATAN + ALIF, current + KASRATAN, current + DAMMATAN].join(' '), ['tanwin'])
  // 8. Gʻunna: nun or mim with tashdid, once one of them has been learned.
  const nasals = pool.filter((letter) => NASAL.includes(letter))
  if (nasals.length > 0) {
    const nasal = pick(nasals)
    const before = current === nasal ? pick(previous) : current
    add(voweled(before, vowel()) + nasal + SHADDA + vowel(), ['shadda', 'ghunna'])
  }

  return drills
}

/** Where a drill's recording lives, e.g. `/audio/drills/03-04.m4a` (lesson 3, drill 4). */
export function drillAudioUrl(lessonOrder: number, index: number): string {
  const pad = (n: number) => String(n).padStart(2, '0')
  return `/audio/drills/${pad(lessonOrder)}-${pad(index + 1)}.m4a`
}

/** Stable drill id: lesson × 100 + position, e.g. 304 = lesson 3, drill 4. */
export function drillId(lessonOrder: number, index: number): number {
  return lessonOrder * 100 + index + 1
}
